-- Emission factor library: factors move from code (src/lib/emission-factors.ts) to the database
-- so admins can import new sources and the Copilote can tag them (sectors, site types, keywords).
-- Idempotent: tables IF NOT EXISTS, seed ON CONFLICT DO NOTHING (never overwrites an admin edit).
-- Seed generated from src/lib/emission-factors.ts (139 factors).

CREATE TABLE IF NOT EXISTS emission_factors (
  id                 VARCHAR(100) PRIMARY KEY,
  category           VARCHAR(50)  NOT NULL,
  subcategory        VARCHAR(50)  NOT NULL,
  name               VARCHAR(300) NOT NULL DEFAULT '',
  name_fr            VARCHAR(300) NOT NULL,
  unit               VARCHAR(100) NOT NULL,
  factor_upstream    NUMERIC      NOT NULL DEFAULT 0,
  factor_combustion  NUMERIC      NOT NULL DEFAULT 0,
  factor_total       NUMERIC      NOT NULL CHECK (factor_total >= 0),
  scope              SMALLINT     NOT NULL CHECK (scope IN (1, 2, 3)),
  ghg_category       VARCHAR(200) NOT NULL DEFAULT '',
  iso_category       VARCHAR(20)  NOT NULL DEFAULT '',
  source             VARCHAR(200) NOT NULL,
  source_ref         VARCHAR(200) NOT NULL DEFAULT '',
  source_year        SMALLINT,
  region             VARCHAR(100) NOT NULL DEFAULT '',
  uncertainty        NUMERIC,
  licence            VARCHAR(100) NOT NULL DEFAULT '',
  keywords           TEXT[]       NOT NULL DEFAULT '{}',
  sectors            TEXT[]       NOT NULL DEFAULT '{}',
  site_types         TEXT[]       NOT NULL DEFAULT '{}',
  is_recommended     BOOLEAN      NOT NULL DEFAULT FALSE,
  status             VARCHAR(20)  NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'retired')),
  created_at         TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at         TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_emission_factors_category ON emission_factors (category, subcategory);

-- Audit trail of every admin change (import, edit, retire). Bilans keep their own copy of the value used.
CREATE TABLE IF NOT EXISTS emission_factor_changes (
  id          SERIAL PRIMARY KEY,
  factor_id   VARCHAR(100) NOT NULL,
  action      VARCHAR(20)  NOT NULL CHECK (action IN ('created', 'updated', 'retired', 'restored')),
  before      JSONB,
  after       JSONB,
  batch_label VARCHAR(200),
  changed_by  INTEGER REFERENCES users(id) ON DELETE SET NULL,
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_emission_factor_changes_factor ON emission_factor_changes (factor_id, created_at DESC);

